/**
 * One durable unresolved source condition found while calculating a revision.
 *
 * Resolver diagnostics are useful calculate-time operator feedback, but a
 * filing-grade verification runs later against the persisted calculation
 * revision. This narrow envelope carries a source condition that reached no
 * binding, without misrepresenting it as source provenance for a computed
 * output.
 *
 * Every reason below must survive to the persisted revision, because each
 * describes a condition the filing cannot treat as complete.
 * `unrouted_observation` is a row no binding consumes at all.
 * `unrouted_declarable_quantity` is an independent quantity that consumed rows
 * carry and no binding drawing that quantity reaches â€” the row-keyed screens
 * are silent on it by construction, so a verify or export gate that saw only
 * the row condition would read their silence as confirmation.
 * `iva_selected_scope_evidence_failure` is a ledger IVA row whose selected
 * filing scope cannot be completed from its recorded tax evidence.
 * `iva_compensation_annual_source_evidence_failure` is a required Modelo 390
 * annual partition whose filed Modelo 303 source set is incomplete or stale.
 * `withholding_detail_absent` is an annual withholding summary whose per-
 * perceptor-clave detail store held no observation for the year, so its
 * percepciones count rests on a zero the store cannot support. A contradictory
 * source is refused during calculation before a revision can be persisted.
 *
 * The remaining reasons each mean a filed figure is missing or cannot be
 * trusted. `unresolved_binding` is a box printed on the form whose declared
 * source produced no value, named by `casilla_id`, which must never read as a
 * zero. `unhandled_binding_source` is a declared source with no executable
 * route. `source_domain_not_ready` is a source store that could not be read
 * yet. `invoice_reverse_charge_cuota_not_derivable` is a reverse-charge
 * invoice whose IVA owed could not be derived. `m349_operation_unclassified`
 * is an invoice with a party in another member state and no cuota whose Modelo
 * 349 operation no record states, so the recapitulativa leaves it out. These
 * block filing until a recalculation clears them. `terminal_origin_mismatch`
 * is a value that reached the declaration by an undeclared route; it persists
 * so a reopened declaration still shows it, but withholds nothing, because the
 * route it reports may lack a terminal origin by design.
 * `ledger_amortization_row_unregistered` is a ledger row in an amortization
 * category no registered element owns. `activity_asset_foral_territory` is a
 * period in a foral territory, whose amortization is determined under foral
 * rules. `activity_asset_residence_unresolved` is a tax residence that could
 * not be read while the register holds elements. These three persist in the
 * same way: the amortization is left out and the rest of the declaration
 * stands. The other activity-asset reasons persist as durable notes for the
 * same cause: what was known about the register at calculation stays with the
 * filed record. None of them withholds anything. `advisory_binding_value` is a
 * value a binding produced whose declared grade cap stops it at calculation:
 * it names the box the value reaches and the binding, and withholds filing
 * until a recalculation under an uncapped binding clears it. `value_outcome`
 * is what the resolver stated beside that value: a proven zero persists too,
 * so a reopened declaration still shows the zero was proven, and withholds
 * nothing; a capped note without a stated outcome withholds. Only that reason
 * carries an outcome. `credit_source_disagreement` is a credit casilla whose
 * value source and a declared cross-check source differ by any amount; it
 * carries the whole `SourceDisagreementFact` in `disagreement` and withholds
 * filing. `credit_cross_check_absent` is a declared cross-check source with
 * nothing to compare, which reads "not cross-checked", never agreement, and
 * withholds nothing. `credit_resolution_stale` is a figure the operator
 * accepted that is now disputed in another way than the one accepted: the
 * resolution no longer covers it, the disagreement it restates still withholds
 * filing, and the note itself withholds nothing. `fact` states such a note's
 * own row, element, interval and amount. `binding_source` is `None` only where
 * the condition names no binding source kind. outcome.
 * `household_rows_incomplete` is a household group whose stated count is
 * larger than the rows the profile records: the recorded rows are used and the
 * group is not proven complete; it withholds nothing.
 * `household_row_fact_unstated` is a stored household row that omits a fact
 * the official design requires of every row, such as an ascendant's NIF: it
 * withholds checking, exporting and filing until the profile states the fact.
 * `ascendant_disability_minimum_not_computed` is an ascendant the mínimo por
 * ascendientes reaches whose grade reaches the disability threshold: the
 * disability minimum for that ascendant is not computed, so it withholds
 * checking, exporting and filing rather than leave the minimum silently out.
 * `income_family_not_computed` is an income family the taxpayer has, by
 * classified ledger rows or a profile declaration, and the application has no
 * calculator for: it withholds checking, exporting and filing until the
 * family's casillas are entered by hand. `fact` states such a note's own row,
 * element, interval and amount. `binding_source` is `None` only where the
 * condition names no binding source kind. `precedence_tier_divergence` is a
 * filed figure for which a higher source tier replaced a different value a
 * lower tier held; `disagreement` states every tier's value and which one the
 * calculation used, and it withholds filing until the sources agree.
 * `disagreement` is carried by exactly the reasons in `DISAGREEMENT_REASONS`.
 */
export type CalculationSourceIssue = {
  reason:
    | "unrouted_observation"
    | "unrouted_declarable_quantity"
    | "iva_selected_scope_evidence_failure"
    | "iva_compensation_annual_source_evidence_failure"
    | "withholding_detail_absent"
    | "unresolved_binding"
    | "terminal_origin_mismatch"
    | "unhandled_binding_source"
    | "source_domain_not_ready"
    | "invoice_reverse_charge_cuota_not_derivable"
    | "m349_operation_unclassified"
    | "ledger_amortization_row_unregistered"
    | "activity_asset_foral_territory"
    | "activity_asset_residence_unresolved"
    | "activity_asset_claim_gap"
    | "activity_asset_accrual_unavailable"
    | "activity_asset_activity_undeclared"
    | "activity_asset_agrarian_excluded"
    | "activity_asset_residence_period_unknown"
    | "activity_asset_disposal_finding"
    | "register_acquisition_exceeds_ledger"
    | "register_acquisition_partly_accounted"
    | "register_acquisition_row_missing"
    | "register_owned_capital_acquisition"
    | "inventory_book_claimed_purchase"
    | "ledger_expense_may_be_durable"
    | "household_rows_incomplete"
    | "household_row_fact_unstated"
    | "ascendant_disability_minimum_not_computed"
    | "income_family_not_computed"
    | "advisory_binding_value"
    | "credit_source_disagreement"
    | "credit_cross_check_absent"
    | "credit_resolution_stale"
    | "precedence_tier_divergence";
  binding_source: BindingSourceKind | null;
  message: string;
  resolver_id: string | null;
  source_ref: string | null;
  casilla_id: CasillaId | null;
  fact: CalculationNoteFact | null;
  value_outcome: BindingValueOutcome | null;
  disagreement: SourceDisagreementFact | null;
};

/**
 * One resolver-level source-object trace persisted on a calculation revision.
 *
 * The calculation source mesh (`cadrumo.application.aggregation`) resolves
 * each registry binding source through an enrolled resolver and produces a
 * typed `CalculationSourceProvenance` row per contributing source object. This
 * is the DOMAIN-side, persistence-shaped projection of that provenance: it
 * carries exactly the resolverâ†’source-objectâ†’fingerprint trace that lets
 * an audit reader reconstruct which resolver mesh and which upstream source
 * objects produced a revision, and whether those objects have since drifted.
 *
 * It deliberately does NOT carry `legal_refs` / `source_refs` â€” those are
 * the per-casilla regulatory grounding already carried by `CasillaObservation`
 * on the same revision; duplicating them here would fragment the grounding
 * across two surfaces.
 *
 * `source_casilla_ids` is NOT grounding and the rationale above does not
 * extend to it. It is a subject IDENTITY -- which casilla(s), if any, this
 * source object's resolution feeds -- and nothing else on the revision carries
 * it for the general (non-row-materialized) case; dropping it here was an
 * omission the application-side `CalculationSourceProvenance` did not itself
 * make (it already carries the field). An empty tuple is honest when the
 * originating resolver call site did not associate this row with a casilla â€”
 * it is not fabricated as a claim of "no subject", only carried as "not linked
 * at resolution time".
 *
 * Attributes: resolver_id: Exact canonical resolver identity that produced
 * this row. resolved_binding_source: Canonical binding source owned by the
 * resolver. contributor_source_kind: Upstream taxonomy token for this source
 * node. contributor_binding_source: Canonical `BindingSourceKind` when
 * `contributor_source_kind` belongs to the binding taxonomy; `None` for an
 * external or non-binding contributor. lineage_role: Whether this row is the
 * resolver-owned primary or supporting contributor. source_ref: Stable
 * reference to the contributing source object (e.g.
 * `collectible_invoice:{invoice_id}`). fingerprint: Data-dependent digest of
 * the contributing source object when the resolver produced one; `None` when
 * the resolver emits a reference without a content digest. source_casilla_ids:
 * Casilla identities this source object's resolution feeds, when the
 * originating resolver associated one; empty when it did not. Carried straight
 * from `source_casilla_ids`. dependency_treatment: The registry's declared
 * dependency treatment for this carry, empty when the revision declares none.
 * Unlike `legal_refs` / `source_refs` this carries no grounding duplicated
 * elsewhere on the revision â€” it is the sole persisted trace of whether a
 * carry is a `factual_evidence` fact to reconcile against or a
 * `direct_annual_settlement` figure that settles the return, and an audit
 * reader has no other way to recover that distinction after the fact. Carried
 * here rather than gated here: the value is NOT withheld on the basis of its
 * treatment. source_filing_year: The filing year of the source this node rests
 * on, when the resolver recorded one: the source modelo's year for a relation
 * carry, and the accrual year for a Modelo 193 disclosure phase row, which
 * tells a pending row from a settled prior-accrual one. `None` means the year
 * is unknown, including on every revision persisted before the field existed;
 * it never means "the current year". It joins the revision identity only when
 * present, so those revisions keep their content-addressed ids.
 */
export type CalculationSourceRef = {
  resolver_id: string;
  resolved_binding_source: BindingSourceKind;
  contributor_source_kind: string;
  contributor_binding_source: BindingSourceKind | null;
  lineage_role: CalculationSourceLineageRole;
  source_ref: string;
  parent_source_ref: string | null;
  fingerprint: string | null;
  source_casilla_ids: CasillaId[];
  dependency_treatment: string;
  source_filing_year: number | null;
};

/**
 * Stable codes for conditions a reconciliation reports to the operator.
 *
 * * `CONTENT_UNAVAILABLE` -- the entry carries neither casillas nor a
 * comparable receipt, or carries no casillas to record AEAT content from. *
 * `RECEIPT_TOTALS_NOT_RECONCILED` -- the receipt total could not be compared;
 * `reason` names why. * `RECEIPT_TOTALS_MISMATCH` -- the receipt total
 * disagrees with the pending entry, but without casillas the AEAT content
 * cannot be recorded. * `RECEIPT_TOTALS_ONLY` -- a confirmation rests on
 * receipt totals rather than per-casilla equality. *
 * `DECLARATION_KIND_MISMATCH` -- AEAT states a different declaration kind than
 * the pending entry. * `DECLARATION_KIND_UNDETERMINED` -- AEAT presents after
 * a confirmed declaration without stating the correction kind. *
 * `CORRECTION_WITHOUT_CONFIRMED_BASELINE` -- AEAT states a correction kind but
 * the chain holds no confirmed declaration to link it to. *
 * `FILING_INSTANCE_EVIDENCE_UNAVAILABLE` -- the modelo's content can only be
 * recorded with its filing-instance evidence, which the entry lacks.
 */
export type FilingReconciliationNoticeCode =
  | "content_unavailable"
  | "receipt_totals_not_reconciled"
  | "receipt_totals_mismatch"
  | "receipt_totals_only"
  | "declaration_kind_mismatch"
  | "declaration_kind_undetermined"
  | "correction_without_confirmed_baseline"
  | "filing_instance_evidence_unavailable";

/**
 * Closed result of reconciling one AEAT register entry.
 */
export type FilingReconciliationOutcome =
  | "already_recorded"
  | "confirmed"
  | "contradicted"
  | "appended"
  | "unverifiable";

